function legacy_json_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function legacy_json_date($v,$fallback=null){$v=trim((string)$v);if($v==='')return $fallback;try{$d=new DateTime($v);$d->setTimezone(new DateTimeZone('Asia/Kolkata'));return $d->format('Y-m-d');}catch(Throwable $e){return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)?$v:$fallback;}}
function legacy_json_datetime($date,$time=''){ $date=legacy_json_date($date);$time=trim((string)$time);if(!$date||!preg_match('/^\d{1,2}:\d{2}(?::\d{2})?$/',$time))return null;$p=explode(':',$time);return sprintf('%s %02d:%02d:%02d',$date,(int)$p[0],(int)$p[1],(int)($p[2]??0)); }
function legacy_json_shift($s,$p=''){ $s=strtolower(trim((string)$s));$p=strtolower(trim((string)$p));$r=strpos($p,'reserved')!==false;if(strpos($s,'morning')!==false)return $r?'Morning Shift Reserved':'Morning Shift';if(strpos($s,'evening')!==false)return $r?'Evening Shift Reserved':'Evening Shift';return $r?'Full Day Reserved':'Full Day'; }
function legacy_json_plan_duration($from,$to,$cat=''){ $c=trim((string)$cat);if(in_array($c,['1','1 Month'],true))return '1 Month';if(in_array($c,['3','3 Months'],true))return '3 Months';if(in_array($c,['6','6 Months'],true))return '6 Months';$a=legacy_json_date($from);$b=legacy_json_date($to);if($a&&$b){$d=(new DateTime($a))->diff(new DateTime($b))->days+1;if($d>=175)return '6 Months';if($d>=80)return '3 Months';if($d>=20&&$d<=45)return '1 Month';}return 'Custom'; }
function legacy_json_mode($v){$v=trim((string)$v);foreach(['Cash','UPI','Online','Bank','Card','Other'] as $x)if(strcasecmp($x,$v)===0)return $x;return $v===''?'Cash':'Other';}
function legacy_json_receipt($base,&$seen){$base=preg_replace('/[^A-Za-z0-9_-]/','-',(string)$base);$base=substr($base?:'OLD-FEE',0,45);$c=$base;$i=2;while(isset($seen[$c])){$s='-'.$i++;$c=substr($base,0,50-strlen($s)).$s;}$seen[$c]=true;return $c;}
