      if($paid>0){$type=$due>0?'Split':'Full';$extra=0.0;$s=$conn->prepare('INSERT INTO payments(receipt_no,member_id,member_code,amount,fee_amount,additional_charges,payment_type,payment_date,payment_method,plan,notes,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');if(!$s)throw new RuntimeException('Could not prepare payment import.');$s->bind_param('sisdddssssss',$receipt,$m['id'],$m['code'],$paid,$paid,$extra,$type,$date,$mode,$plan,$notes,$created);if(!$s->execute()){$e=$s->error;$s->close();throw new RuntimeException('Payment '.$receipt.' failed: '.$e);}$s->close();$st='Paid';$s=$conn->prepare('INSERT INTO member_fees(member_id,receipt_no,amount,payment_date,due_date,payment_method,status,remarks,created_at) VALUES(?,?,?,?,?,?,?,?,?)');if(!$s)throw new RuntimeException('Could not prepare paid fee import.');$s->bind_param('isdssssss',$m['id'],$receipt,$paid,$date,$date,$mode,$st,$notes,$created);if(!$s->execute()){$e=$s->error;$s->close();throw new RuntimeException('Paid fee history failed: '.$e);}$s->close();$counts['Fee payments imported']++;}
      if($due>0){$dr=$receipt.'-D';$st='Pending';$rem='Imported legacy pending balance'.($notes!==''?': '.$notes:'');$s=$conn->prepare('INSERT INTO member_fees(member_id,receipt_no,amount,payment_date,due_date,payment_method,status,remarks,created_at) VALUES(?,?,?,?,?,?,?,?,?)');if(!$s)throw new RuntimeException('Could not prepare pending fee import.');$s->bind_param('isdssssss',$m['id'],$dr,$due,$date,$date,$mode,$st,$rem,$created);if(!$s->execute()){$e=$s->error;$s->close();throw new RuntimeException('Pending fee history failed: '.$e);}$s->close();$counts['Pending dues imported']++;}
     }
     foreach(($data['attendance']??[]) as $a){$old=trim((string)($a['memberId']??''));if(!isset($map[$old]))continue;$date=legacy_json_date($a['date']??'',null);if(!$date)continue;$in=legacy_json_datetime($a['date']??'',$a['in']??'');$out=legacy_json_datetime($a['date']??'',$a['out']??'');$st=$out?'Closed':'Open';$rem=trim((string)($a['shift']??''));$created=legacy_json_date($a['createdAt']??'',$date);$s=$conn->prepare('INSERT INTO attendance(member_id,attendance_date,check_in,check_out,status,remarks,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(member_id,attendance_date) DO UPDATE SET check_in=excluded.check_in,check_out=excluded.check_out,status=excluded.status,remarks=excluded.remarks');if(!$s)throw new RuntimeException('Could not prepare attendance import.');$s->bind_param('isssssss',$map[$old]['id'],$date,$in,$out,$st,$rem,$created,$created);if(!$s->execute()){$e=$s->error;$s->close();throw new RuntimeException('Attendance import failed: '.$e);}$s->close();$counts['Attendance imported']++;}
     foreach($data['members'] as $m){$old=trim((string)($m['id']??''));$seat=trim((string)($m['seat']??''));if($seat===''||!isset($map[$old]))continue;$start=legacy_json_date($m['from']??'',date('Y-m-d'));$end=legacy_json_date($m['to']??'',null);$st='Assigned';$rem='Imported from legacy backup';$created=legacy_json_date($m['createdAt']??'',$start);$s=$conn->prepare('INSERT INTO member_seats(member_id,seat_no,shift,start_date,end_date,status,remarks,created_at) VALUES(?,?,?,?,?,?,?,?)');if(!$s)throw new RuntimeException('Could not prepare seat import.');$s->bind_param('isssssss',$map[$old]['id'],$seat,$map[$old]['shift'],$start,$end,$st,$rem,$created);if(!$s->execute()){$e=$s->error;$s->close();throw new RuntimeException('Seat import failed: '.$e);}$s->close();$counts['Seats imported']++;}
