     foreach(($data['expenses']??[]) as $e2){$date=legacy_json_date($e2['date']??'',date('Y-m-d'));$cat=trim((string)($e2['cat']??'Other'))?:'Other';$desc=trim((string)($e2['desc']??''));$amt=max(0,(float)($e2['amount']??0));if($amt<=0)continue;$mode=legacy_json_mode($e2['mode']??'Cash');$notes=trim((string)($e2['notes']??''));$created=legacy_json_date($e2['createdAt']??'',$date);$vendor='';$s=$conn->prepare('INSERT INTO expenses(expense_date,category,description,amount,payment_method,vendor,notes,created_at) VALUES(?,?,?,?,?,?,?,?)');if(!$s)throw new RuntimeException('Could not prepare expense import.');$s->bind_param('sssdssss',$date,$cat,$desc,$amt,$mode,$vendor,$notes,$created);if(!$s->execute()){$e3=$s->error;$s->close();throw new RuntimeException('Expense import failed: '.$e3);}$s->close();$counts['Expenses imported']++;}
