acy_json" accept="application/json,.json" required><button class="btn" type="submit" onclick="return confirm('Old JSON data current database me import karna hai? Current Admin account/password unchanged rahega.')">Import Legacy JSON</button></form><?php endif; ?><p class="muted" style="margin-top:20px">After a successful one-time import, this file can be removed from the server.</p><p><a href="index.php">← Back to AR Library</a></p></div></div></body></html>
